import { HttpClient } from '@angular/common/http';
import { inject, Injectable } from '@angular/core';
import { Observable } from 'rxjs';
import { RouteAiResponse } from '../interfaces/route-ai.interface';

@Injectable({
  providedIn: 'root',
})
export class RouteService {

  private _http = inject(HttpClient)

  /** GET routes generated by AI and request from the user authenticated. */
  getRoutesAiUser(): Observable<RouteAiResponse[]> {
    return this._http.get<RouteAiResponse[]>('ai-route')
  }
}
